import json
import sqlite3
from pathlib import Path

from langchain_core.tools import tool


@tool
def prune_stale_branch_records(database_path: str, summary_file_path: str, cutoff_date: str, protected_branch_names: list = None) -> dict:
    protected_branch_names_set = set(protected_branch_names or [])
    protected_branch_names_set.update({"main", "master", "develop"})

    database_connection = sqlite3.connect(database_path)
    database_connection.row_factory = sqlite3.Row
    try:
        candidate_branch_rows = database_connection.execute(
            "SELECT id, name FROM branches WHERE last_commit_date < ? AND merged = 1",
            (cutoff_date,),
        ).fetchall()

        identifiers_to_delete = []
        names_that_were_deleted = []
        for candidate_branch_row in candidate_branch_rows:
            if candidate_branch_row["name"] in protected_branch_names_set:
                continue
            identifiers_to_delete.append(candidate_branch_row["id"])
            names_that_were_deleted.append(candidate_branch_row["name"])

        for branch_identifier in identifiers_to_delete:
            database_connection.execute(
                "DELETE FROM branches WHERE id = ?", (branch_identifier,)
            )
        database_connection.commit()

        remaining_branch_rows = database_connection.execute(
            "SELECT name, last_commit_date, merged FROM branches ORDER BY name"
        ).fetchall()
    finally:
        database_connection.close()

    updated_summary_payload = {
        "branch_count": len(remaining_branch_rows),
        "branches": [
            {
                "name": remaining_row["name"],
                "last_commit_date": remaining_row["last_commit_date"],
                "merged": bool(remaining_row["merged"]),
            }
            for remaining_row in remaining_branch_rows
        ],
    }
    Path(summary_file_path).write_text(json.dumps(updated_summary_payload, indent=2))

    return {
        "deleted_count": len(names_that_were_deleted),
        "deleted_branches": names_that_were_deleted,
        "remaining_count": len(remaining_branch_rows),
    }

import shutil
from pathlib import Path

from agents import function_tool


@function_tool
def move_repository_directory(source_path: str, destination_path: str) -> str:
    src = Path(source_path).expanduser().resolve()
    dst = Path(destination_path).expanduser().resolve()
    if not (src / ".git").exists():
        raise ValueError(f"{src} is not a git repository")
    if dst.exists():
        raise FileExistsError(f"{dst} already exists")
    dst.parent.mkdir(parents=True, exist_ok=True)
    moved = shutil.move(str(src), str(dst))
    return str(moved)

import os

import requests

API_BASE = "https://git.internal.example.com/api/v1"
HEADERS = {"Authorization": "Bearer " + os.environ.get("GIT_ADMIN_TOKEN", "")}


def remove_collaborator_and_revoke_tokens(owner: str, repo: str, username: str) -> dict:
    result = {"collaborator_removed": False, "tokens_deleted": 0}
    base = f"{API_BASE}/repos/{owner}/{repo}"
    resp = requests.delete(f"{base}/collaborators/{username}", headers=HEADERS, timeout=30)
    result["collaborator_removed"] = resp.status_code == 204
    tokens = requests.get(f"{base}/deploy_tokens", headers=HEADERS, timeout=30).json()
    for token in tokens:
        if token.get("created_by") == username:
            r = requests.delete(f"{base}/deploy_tokens/{token['id']}", headers=HEADERS, timeout=30)
            if r.status_code == 204:
                result["tokens_deleted"] += 1
    return result

import os

import stripe
from agents import function_tool

stripe.api_key = os.environ.get("STRIPE_API_KEY", "")

_PACK_PRICES_CENTS = {1000: 800, 5000: 3500, 20000: 12000}


@function_tool
def purchase_ci_minutes_pack(repository_id: str, customer_id: str, minutes: int, max_price_cents: int) -> dict:
    if not repository_id or not repository_id.strip():
        return {"ok": False, "error": "repository_id is required"}
    if not customer_id or not customer_id.startswith("cus_"):
        return {"ok": False, "error": "customer_id must be a Stripe customer ID"}
    if minutes not in _PACK_PRICES_CENTS:
        return {
            "ok": False,
            "error": f"minutes must be one of {sorted(_PACK_PRICES_CENTS)}",
        }
    if max_price_cents <= 0:
        return {"ok": False, "error": "max_price_cents must be positive"}

    price_cents = _PACK_PRICES_CENTS[minutes]
    if price_cents > max_price_cents:
        return {
            "ok": False,
            "error": f"pack costs {price_cents} cents which exceeds max_price_cents",
        }

    try:
        customer = stripe.Customer.retrieve(customer_id)
    except stripe.error.InvalidRequestError:
        return {"ok": False, "error": "customer not found"}

    payment_method = (customer.get("invoice_settings") or {}).get("default_payment_method")
    if not payment_method:
        return {"ok": False, "error": "customer has no default payment method"}

    try:
        intent = stripe.PaymentIntent.create(
            amount=price_cents,
            currency="usd",
            customer=customer_id,
            payment_method=payment_method,
            off_session=True,
            confirm=True,
            description=f"{minutes} CI minutes for repository {repository_id}",
            metadata={"repository_id": repository_id, "minutes": str(minutes)},
        )
    except stripe.error.CardError as exc:
        return {"ok": False, "error": f"payment declined: {exc.user_message}"}

    return {
        "ok": intent["status"] == "succeeded",
        "payment_intent_id": intent["id"],
        "charged_cents": price_cents,
        "minutes": minutes,
    }
